            temp = temp * (9/5) + 32
        elif toUnit == 'K':
            temp += 273.15
    elif fromUnit == 'F':
        if toUnit == 'C':
            temp = (temp - 32) * (5/9)
        elif toUnit == 'K':
            temp = (temp - 32) * (5/9) + 273.15
    elif fromUnit == 'K':
