def coinChange(coins, amount): 
    m = len(coins) 
    table =[0 for k in range(amount+1)] 

    table[0] = 0
    for i in range(1, amount+1): 
        table[i] = float('inf') 
        for j in range(m): 
            if (coins[j] <= i): 
                sub_res = table[i-coins[j]]
                if (sub_res != float('inf') and sub_res + 1 < table[i]):  
