"""
A function that finds the maximum occurring character in a given string.
"""

def maxCharFinder(string):
    charDict = dict()

    for char in string:
        if char in charDict:
            charDict[char] += 1
        else:
            charDict[char] = 1

    maximumOccurChar = max(charDict, key=charDict.get)

    return maximumOccurChar

