"""
Dynamic programming program in Python to solve the knapsack problem 
"""

def knapsack(weights, values, capacity):
    n = len(weights)

    K = [[0 for x in range(capacity+1)] for x in range(n+1)]

    # Build table K[][] in bottom up manner
    for i in range(n+1):
        for w in range(capacity+1):
            if i==0 or w==0:
                K[i][w] = 0
            elif weights[i-1] <= w:
                K[i][w] = max(values[i-1] + K[i-1][w-weights[i-1]],  K[i-1][w])
            else:
                K[i][w] = K[i-1][w]

    # stores the result of Knapsack
    res = K[n][capacity]
    return res

def is_power_two(num):
    if num == 0:
        return False

    while num != 1:
        if num % 2 != 0:
            return False
        num = num // 2
    return True

