def minCoins(amount):  

    # Initializing the list of coins with the given amount 
    coins = [1, 2, 5] 
    num_coins = [999999999] * (amount+1) 
    num_coins[0] = 0

    for i in range(1, amount+1): 
        for j in coins: 
            if j <= i: 
                sub_res = num_coins[i-j] 
