def largest_subarray_sum(arr):
    # Create an empty dictionary 
    sum_map =  {} 

    sum_value = 0
    max_len = 0

    # Traverse through the array and store the cumulative 
    # sum values in the dictionary
    for i in range(0,len(arr)): 
        sum_value += arr[i] 

        if (sum_value == 0): 
            max_len = i + 1

        if sum_value in sum_map: 
