def knapsack(weights, values, capacity):
 if len(weights) == 0 or len(values) == 0 or capacity == 0:
 return 0

 v = [0 for _ in range(len(weights))]
 for i in range(len(weights)):
 if weights[i] <= capacity:
 v[i] = values[i]

 for i in range(len(weights)):
 for c in range(capacity, weights[i] - 1, -1):
 v[i] = max(v[i], values[i] + v[c - weights[i]])

 return v[capacity]

