def perms_help(nums, l, r, result): 
    if l == r: 
        result.append("".join(nums)) 
    else: 
        for i in range(l, r + 1):
            # swap character
            nums[l], nums[i] = nums[i], nums[l]
            # recur
            perms_help(nums, l + 1, r, result)
            # backtrack
            nums[l], nums[i] = nums[i], nums[l]

