        self.length = length

    def generate_password(self):
        chars = string.ascii_letters + string.digits + '!@#$%^&*()?'
        random_chars = ''.join(random.sample(chars, self.length))

        uppercase_chars = [char for char in random_chars if char.isupper()]
        lowercase_chars = [char for char in random_chars if char.islower()]
        digits = [char for char in random_chars if char.isdigit()]
        special_chars = [char for char in random_chars if not char.isalnum()]

