class BinaryTree:

   def __init__(self):
       self.root = None

   def add_node(self, data):
        if self.root is None:
            self.root = Node(data)
        else:
            self._add_to_tree(self.root, data)

    def _add_to_tree(self, node, data):
        if data < node.data:
            if node.left is None:
                node.left = Node(data)
            else:
                self._add_to_tree(node.left, data)
        else:
            if node.right is None:
                node.right = Node(data)
            else:
                self._add_to_tree(node.right, data)

    def max_depth(self):
        return self._max_depth(self.root)

    def _max_depth(self, node):
        if node is None:
            return 0
        else:
            left_depth = self._max_depth(node.left) 
            right_depth = self._max_depth(node.right)
            return max(left_depth, right_depth) + 1

