def getmiddle(head): 
    if(head == None): 
        return head 

    slow_ptr = head 
    fast_ptr = head 

    while(fast_ptr != None and fast_ptr.next != None): 
        slow_ptr = slow_ptr.next
        fast_ptr = fast_ptr.next.next

    return slow_ptr

