def classify_numbers(lst):
    result = []
    for num in lst:
        if num <= 1:
            result.append("Composite")
        elif num == 2:
            result.append("Prime")
        elif num % 2 == 0:
            result.append("Even")
        else:
            is_prime = True
            for i in range(2, int(num**0.5)+1):
                if num % i == 0:
                    is_prime = False
                    break
            if is_prime:
                result.append("Prime")
            else:
                result.append("Odd")
    return result

