def is_armstrong(num):
   # calculate the total of each digits power to the length of digits 
    temp = num
    order = len(str(num))
    sum = 0
    while temp > 0:
        digit = temp % 10
        sum += digit ** order
        temp //= 10

    if (num == sum):
        return True
    else:
        return False 

def find_armstrong_numbers(start, end):
    armstrong_numbers = []
    for num in range(start, end + 1):
        if is_armstrong(num):
            armstrong_numbers.append(num)
    return armstrong_numbers

def pattern_search(string, pattern):
    i = 0
    while i < len(string):
        j = 0
        while j < len(pattern):
            if string[i+j] != pattern[j]:
                break
            j += 1
        if j == len(pattern):
            return i
        i += 1
    return -1

